"""Typed Pydantic data models for LangGraph agents."""

from typing import Any, Literal
from uuid import UUID

from pydantic import BaseModel, Field


class TaskPlan(BaseModel):
    """Execution plan generated by Node 01 Planner."""

    goal: str
    steps: list[str] = Field(default_factory=list)
    assigned_nodes: list[str] = Field(default_factory=list)


class InputBundle(BaseModel):
    """Input payload bundle validated by Node 02 Intake."""

    kind: str
    media_ids: list[UUID] = Field(default_factory=list)
    storage_keys: list[str] = Field(default_factory=list)
    raw_text: str | None = None
    audio_bytes: bytes | None = None
    mime_type: str | None = None


class ContextBundle(BaseModel):
    """Confirmed background context gathered by Node 03 Context."""

    matching_products: list[dict[str, Any]] = Field(default_factory=list)
    matching_skus: list[str] = Field(default_factory=list)
    policies: list[dict[str, Any]] = Field(default_factory=list)


class PolicyDecision(BaseModel):
    """Guardrail decision returned by deterministic policy gate."""

    decision: Literal["allow", "require_approval", "deny"]
    reason: str
    rule: str = "default_policy"
    evidence_ids: list[UUID] = Field(default_factory=list)


class ConflictRecord(BaseModel):
    """Record of conflicting values between proposed facts and confirmed database facts."""

    field: str
    incoming_value: Any
    existing_value: Any
    severity: Literal["low", "medium", "high"] = "high"
    ask_seller: bool = True


class UncertaintyRecord(BaseModel):
    """Record of low-confidence extracted fields requiring seller clarification."""

    field: str
    suggested_value: Any = None
    confidence: float = 0.0
    ask_seller: bool = True
    reason: str | None = None
